/* =====================================================================
   Rumo Socioeconómico — Base de dados de universidades europeias
   ---------------------------------------------------------------------
   Cada universidade é criada com a função u(...), com estes campos:
     nome, cidade, nivel (1 a 5 = dificuldade de admissão),
     areas (categorias de curso), desc (descrição), req (requisitos),
     link (site oficial), wiki (artigo da Wikipédia usado para a foto)
     e cursos (licenciaturas abertas a alunos internacionais, no formato
     "Nome do curso|LÍNGUA; ...").

   Dificuldade de entrada (campo nivel, de 1 a 5), agrupada em 3 grupos:
     1, 2 e 3 -> DIFÍCIL  |  4 -> MODERADO  |  5 -> FÁCIL
   NOTA: médias, requisitos e cursos são valores de referência.
   Confirmar sempre no site oficial de cada universidade.
   ===================================================================== */

// Abreviaturas das 9 áreas de estudo
const G = "Gestão e Administração";
const E = "Economia";
const F = "Finanças e Contabilidade";
const M = "Marketing e Comunicação";
const D = "Direito e Relações Internacionais";
const R = "Recursos Humanos e Ciências Sociais";
const T = "Tecnologia e Análise de Dados";
const L = "Turismo, Comércio e Logística";
const O = "Outras áreas";

// Nomes das línguas de ensino
const LINGUAS = {
    EN: "Inglês", ES: "Espanhol", FR: "Francês", DE: "Alemão", IT: "Italiano", NL: "Neerlandês",
    DA: "Dinamarquês", SV: "Sueco", NO: "Norueguês", FI: "Finlandês", IS: "Islandês", PL: "Polaco",
    CS: "Checo", SK: "Eslovaco", RO: "Romeno", BG: "Búlgaro", EL: "Grego", ET: "Estónio",
    SL: "Esloveno", HR: "Croata", SR: "Sérvio", UA: "Ucraniano", SQ: "Albanês", ME: "Montenegrino",
    MK: "Macedónio", TR: "Turco", KA: "Georgiano", HY: "Arménio", AZ: "Azeri", RU: "Russo"
};

// Grupo de dificuldade a partir do nível (1 a 5)
function grupoDificuldade(nivel) {
    if (nivel <= 3) return "dificil";
    if (nivel === 4) return "moderado";
    return "facil";
}

// Fotografias próprias (substituem a foto automática da Wikipédia).
// A imagem está guardada dentro deste ficheiro (formato base64), por isso
// funciona sempre, mesmo sem a pasta imagens/.
const FOTO_LSE = "data:image/jpeg;base64,";

const FOTOS_PROPRIAS = {
    "London School of Economics": FOTO_LSE
};

// Função auxiliar que cria cada universidade
function u(nome, cidade, nivel, areas, desc, req, link, wiki, cursosTexto) {
    const cursos = cursosTexto.split(";").map(c => c.trim()).filter(c => c).map(c => {
        const [nomeCurso, lingua] = c.split("|");
        return { nome: nomeCurso.trim(), linguas: (lingua || "EN").split("/").map(l => l.trim()) };
    });
    return {
        nome, cidade, nivel, grupo: grupoDificuldade(nivel), areas, desc, req, link, wiki,
        foto: FOTOS_PROPRIAS[wiki] || null, cursos
    };
}

